package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogLine;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSettings;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;

/**
 * Closes a period, fixing its due-total as it stands now: the dues (figures plus any late charge, as they are now) of
 * the claims dated in it that count by their status at the period's end, added up (n/a skipped), and each person's
 * share of it (0.00 for a person with none), with the figure carried into it for each person: the dues of their
 * claims from earlier periods still open at its end (see {@link Period#carries}). Used by a close by hand and by the automatic close when today changes.
 */
@Component
public class PeriodCloser {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final PersonRepository people;
    private final PeriodRepository periods;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final SheetRepository sheets;

    public PeriodCloser(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people,
            PeriodRepository periods, RateRepository rates, SettingRepository settings, SheetRepository sheets) {
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.periods = periods;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** The same period, closed with its due-total and each person's due-total fixed as they stand now. */
    public Period close(Period period) {
        return fix(period, false);
    }

    /** The same period, soft-closed with its due-total and each person's due-total fixed as they stand now. */
    public Period softClose(Period period) {
        return fix(period, true);
    }

    private Period fix(Period period, boolean soft) {
        Map<Long, Person> byId = people.findAll(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, Function.identity()));
        List<Rate> sheetRates = rates.findAll(period.sheetId());
        DatedSettings dated = settings.dated(period.sheetId());
        LocalDate today = sheets.today(period.sheetId());
        List<Claim> sheetClaims = claims.findAll(period.sheetId());
        Map<Long, List<ClaimLogLine>> sheetLogs = logs.findAll(period.sheetId());
        Rounding rounding = settings.rounding(period.sheetId(), today, sheetClaims);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        List<Period> sheetPeriods = periods.findAll(period.sheetId());
        Map<Long, BigDecimal> perPerson = new HashMap<>();
        Map<Long, BigDecimal> carried = new HashMap<>();
        for (Long id : byId.keySet()) {
            perPerson.put(id, BigDecimal.ZERO.setScale(2));
            carried.put(id, BigDecimal.ZERO.setScale(2));
        }
        for (Claim claim : sheetClaims) {
            Person person = byId.get(claim.personId());
            if (person == null) {
                continue;
            }
            List<ClaimLogLine> log = sheetLogs.getOrDefault(claim.id(), List.of());
            boolean counts = period.counts(claim, log, person, today);
            boolean carries = period.carries(claim, log, person, today, sheetPeriods);
            if (!counts && !carries) {
                continue;
            }
            BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim),
                    dated.floorOn(claim.date()), dated.lateCharge(today, person), rounding);
            if (figure == null) {
                continue;
            }
            if (counts) {
                total = total.add(figure);
                perPerson.merge(person.id(), figure, BigDecimal::add);
            }
            if (carries) {
                carried.merge(person.id(), figure, BigDecimal::add);
            }
        }
        return soft ? period.softClose(total, perPerson, carried) : period.close(total, perPerson, carried);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogLine;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;

/**
 * A period of a sheet: its name (unique on the sheet) and its from and to dates, both inclusive. A closed
 * period keeps the due-total fixed when it was closed ({@code closedTotal}; null while open) and each person's
 * due-total for it then ({@code personTotals}, by person id; empty while open), with the figure carried into it then
 * ({@code personCarried}, by person id; empty while open). A soft-closed period
 * ({@code softClosed}; never also {@code closed}) keeps its figures fixed the same way, but claims due by a date in it can
 * still be added and changed. {@code cap} is the most OPEN or PENDING claims due by a date in it a person may have
 * when another of theirs is opened (null: no cap).
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, Map<Long, BigDecimal> personTotals, boolean softClosed, Integer cap,
        Map<Long, BigDecimal> personCarried) {

    /** A new, open period with no cap. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, null);
    }

    /** A new, open period with this cap (null: none). */
    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to, false, null, Map.of(), false, cap, Map.of());
    }

    /** Whether the period's figures are fixed: it is closed or soft-closed. */
    public boolean fixed() {
        return closed || softClosed;
    }

    /** Whether the period shares a day with the other. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to()) && !other.from().isAfter(to);
    }

    /** Whether the date falls in the period, both ends included. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /**
     * The status the claim had at the end of the period's last day, as its status log (oldest first) records it: the
     * last line logged on or before it; null when it was added after. A claim with no log is taken at its status now.
     */
    public ClaimStatus statusAtEnd(Claim claim, List<ClaimLogLine> log) {
        if (log.isEmpty()) {
            return claim.status();
        }
        ClaimStatus status = null;
        for (ClaimLogLine line : log) {
            if (!line.date().isAfter(to)) {
                status = line.status();
            }
        }
        return status;
    }

    /**
     * Whether the claim counts toward the period: due by a date in it and OPEN, PENDING or SETTLED at the period's end, left
     * out as the live rules say while it is deferred on today, or when it was open then, is open still, a hold of its
     * person covers it (or their retirement date is reached) and no statement binds it (a hold leaves out only open
     * claims). A settled claim voided since leaves it.
     */
    public boolean counts(Claim claim, List<ClaimLogLine> log, Person person, LocalDate today) {
        if (!contains(claim.dueBy())) {
            return false;
        }
        ClaimStatus then = statusAtEnd(claim, log);
        if (then == ClaimStatus.SETTLED) {
            return claim.status() != ClaimStatus.VOID;
        }
        if (then == null || !then.open() || claim.deferred(today)) {
            return false;
        }
        return !claim.status().open() || claim.bound() || !person.heldOn(claim.date(), today);
    }

    /**
     * Whether the claim is carried into the period: due by a date in an earlier period (one that ends before this one
     * starts), still OPEN or PENDING at this period's end, and counted as the period figures count it.
     */
    public boolean carries(Claim claim, List<ClaimLogLine> log, Person person, LocalDate today, List<Period> periods) {
        Period own = periods.stream().filter((p) -> p.contains(claim.dueBy())).findFirst().orElse(null);
        if (own == null || !own.to().isBefore(from)) {
            return false;
        }
        ClaimStatus then = statusAtEnd(claim, log);
        if (then == null || !then.open() || claim.deferred(today)) {
            return false;
        }
        return !claim.status().open() || claim.bound() || !person.heldOn(claim.date(), today);
    }

    /** The same period, closed with its due-total and each person's due-total and carried figure fixed. */
    public Period close(BigDecimal total, Map<Long, BigDecimal> perPerson, Map<Long, BigDecimal> carried) {
        return new Period(sheetId, name, from, to, true, total, Map.copyOf(perPerson), false, cap, Map.copyOf(carried));
    }

    /** The same period, soft-closed with its due-total and each person's due-total and carried figure fixed. */
    public Period softClose(BigDecimal total, Map<Long, BigDecimal> perPerson, Map<Long, BigDecimal> carried) {
        return new Period(sheetId, name, from, to, false, total, Map.copyOf(perPerson), true, cap, Map.copyOf(carried));
    }

    /** The same period with these fixed per-person due-totals and carried figures. */
    public Period withPersonTotals(Map<Long, BigDecimal> perPerson, Map<Long, BigDecimal> carried) {
        return new Period(sheetId, name, from, to, closed, closedTotal, Map.copyOf(perPerson), softClosed, cap,
                Map.copyOf(carried));
    }

    /** The same period, open again with its due-total and carried figures live. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, Map.of(), false, cap, Map.of());
    }
}
package net.officefloor.hq.app.period;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final String COLUMNS = "sheet_id, name, from_date, to_date, closed, closed_total, soft_closed, claim_cap";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, earliest first. */
    public List<Period> findAll(String sheetId) {
        List<Period> periods = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date",
                PeriodRepository::map, sheetId);
        Map<String, Map<Long, BigDecimal>> totals = new HashMap<>();
        Map<String, Map<Long, BigDecimal>> carried = new HashMap<>();
        jdbc.query("SELECT period_name, person_id, total, carried FROM period_person_total WHERE sheet_id = ?",
                (rs) -> {
                    totals.computeIfAbsent(rs.getString("period_name"), (k) -> new HashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                    carried.computeIfAbsent(rs.getString("period_name"), (k) -> new HashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("carried"));
                }, sheetId);
        return periods.stream().map((p) -> p.withPersonTotals(totals.getOrDefault(p.name(), Map.of()),
                carried.getOrDefault(p.name(), Map.of()))).toList();
    }

    /** The sheet's period with this name, or null. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?",
                PeriodRepository::map, sheetId, name);
        if (found.isEmpty()) {
            return null;
        }
        Map<Long, BigDecimal> totals = new HashMap<>();
        Map<Long, BigDecimal> carried = new HashMap<>();
        jdbc.query("SELECT person_id, total, carried FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                (rs) -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                    carried.put(rs.getLong("person_id"), rs.getBigDecimal("carried"));
                }, sheetId, found.get(0).name());
        return found.get(0).withPersonTotals(totals, carried);
    }

    /** The sheet's closed period containing the date, or null. */
    public Period closedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.closed() && p.contains(date)).findFirst().orElse(null);
    }

    /** The sheet's soft-closed period containing the date, or null. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.softClosed() && p.contains(date)).findFirst().orElse(null);
    }

    public void insert(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, claim_cap) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), period.from(), period.to(), period.cap());
    }

    /** Store the period's closed and soft-closed flags, fixed due-total (null when reopened) and fixed per-person due-totals and carried figures. */
    public void saveClosed(Period period) {
        jdbc.update("UPDATE period SET closed = ?, closed_total = ?, soft_closed = ? WHERE sheet_id = ? AND name = ?",
                period.closed(), period.closedTotal(), period.softClosed(), period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        period.personTotals().forEach((personId, total) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total, carried) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, total,
                period.personCarried().getOrDefault(personId, BigDecimal.ZERO.setScale(2))));
    }

    private static Period map(ResultSet rs, int n) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getObject("from_date", LocalDate.class),
                rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"), Map.of(),
                rs.getBoolean("soft_closed"), rs.getObject("claim_cap", Integer.class), Map.of());
    }
}

