import net.officefloor.plugin.variable.Val;

/**
 * Builds each imported person and checks them with the person form's rules against the sheet and its tree (names,
 * aliases, contacts). A line whose name is a person's name or alias on the sheet updates that person as the form's
 * edit does (grade from the sheet's today; terms and contact only when the line gives them); any other line adds a
 * person as the form's add does. Two lines for the same person, or any line refused, refuse the whole import, before
 * anything is written.
 */
public class CheckImportedPeopleUnique {
    public void check(@Val ImportedPeople imported, @Val Sheet sheet, PersonRepository repository, NameTree tree,
            SheetRepository sheets, Out<ImportedPersons> built) throws InvalidPersonException {
        List<ImportedPersons.Entry> people = new ArrayList<>();
        Set<Long> updating = new HashSet<>();
        int number = 0;
        for (PersonRequest request : imported.people()) {
            number++;
            try {
                Person existing = repository.findByName(sheet.id(), request.name());
                if (existing == null) {
                    Person[] person = new Person[1];
                    new BuildPerson().build(request, sheet, value -> person[0] = value);
                    new CheckPersonNameUnique().check(person[0], repository, tree);
                    people.add(new ImportedPersons.Entry(person[0], null));
                    continue;
                }
                if (!updating.add(existing.id())) {
                    throw new InvalidPersonException("The person " + existing.name()
                            + " is already given by an earlier line.");
                }
                PersonRequest edit = new PersonRequest(existing.name(), request.grade(), "", null,
                        request.termsDays() != null ? request.terms()
                                : existing.terms() == null ? "" : String.valueOf(existing.terms()),
                        request.contactOrNull() != null ? request.contact()
                                : existing.contact() == null ? "" : existing.contact(), null);
                Person[] person = new Person[1];
                PersonTermsChange[] change = new PersonTermsChange[1];
                try {
                    new ApplyPerson().apply(edit, existing, sheets, value -> person[0] = value,
                            value -> change[0] = value);
                } catch (StalePersonException e) {
                    throw new InvalidPersonException(e.getMessage());
                }
                new CheckPersonNameUnique().check(person[0], repository, tree);
                people.add(new ImportedPersons.Entry(person[0], change[0]));
            } catch (InvalidPersonException e) {
                throw new InvalidPersonException("Person " + number + ": " + e.getMessage());
            }
        }
        built.set(new ImportedPersons(people));
    }
}
-- Each person's carried figure for a closed or soft-closed period, fixed with their due-total when it was closed:
-- the dues of their claims from earlier periods still open at its end. Cleared with the row when the period reopens.
ALTER TABLE period_person_total ADD COLUMN carried DECIMAL(19, 2) NOT NULL DEFAULT 0;
-- Each person's due-total for a closed period, fixed when it was closed: the dues of their counting claims dated
-- in it. A person with no row here (added after the close) shows 0.00 for it. Cleared when the period reopens.
CREATE TABLE period_person_total (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    period_name VARCHAR(100) NOT NULL,
    person_id BIGINT NOT NULL,
    total DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
package net.officefloor.hq.app.period;

import java.util.Map;
import java.util.TreeMap;

/**
 * A period as the screen shows it: its name, its from and to dates as yyyy-MM-dd, whether it is closed and,
 * when closed, the due-total fixed then (two decimals; null while open) and each person's due-total fixed then, by
 * person id (empty while open), with each person's carried figure fixed then (personCarried), whether it is soft-closed (its figures fixed the same way), and its cap on each
 * person's open claims (null: none).
 */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> personTotals, boolean soft, Integer cap, Map<String, String> personCarried) {

    public static PeriodResponse from(Period period) {
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(), period.closed(),
                period.closedTotal() == null ? null : period.closedTotal().setScale(2).toPlainString(),
                byPerson(period.personTotals()), period.softClosed(), period.cap(), byPerson(period.personCarried()));
    }

    private static Map<String, String> byPerson(Map<Long, java.math.BigDecimal> figures) {
        Map<String, String> totals = new TreeMap<>();
        figures.forEach((id, total) -> totals.put(id.toString(), total.setScale(2).toPlainString()));
        return totals;
    }
}
